import { createHash } from 'node:crypto';
import { mock } from 'bun:test';
import { writeFileSync, appendFileSync, readFileSync, existsSync } from 'node:fs';
import { isDeepStrictEqual } from 'node:util';
const [root, corpusPath, output, selection='all'] = process.argv.slice(2);
if (!root || !corpusPath || !output || existsSync(output)) throw new Error('Expected root corpus new-output [kind]');
if (!process.env.OPENROUTER_API_KEY) throw new Error('Missing OpenRouter key');
if (new URL(process.env.OPENROUTER_BASE_URL || 'https://openrouter.ai').host !== 'openrouter.ai') throw new Error('Unexpected provider host');
const corpusText=readFileSync(corpusPath,'utf8');
const corpus=JSON.parse(corpusText,(key,value)=> ['observedAt','expiresAt'].includes(key) && typeof value==='string' ? new Date(value) : value);
const ids = [...corpus.memoryCases.map((x:any)=>x.id), ...corpus.planningCases.map((x:any)=>x.id), ...corpus.rankingCases.map((x:any)=>x.id), ...corpus.answerFixtures.map((x:any)=>x.turn.scenarioId)];
if (new Set(ids).size !== ids.length) throw new Error('Duplicate fixture IDs');
for (const f of corpus.answerFixtures) if (!f.turn.scenarioId || Object.keys(f.expected).length !== 4) throw new Error('Invalid answer labels');
for (const c of corpus.memoryCases) if(c.expected.length !== c.input.candidates.length) throw new Error('Invalid memory labels');
for (const c of corpus.rankingCases) if(Object.keys(c.expected.rawChoices).length !== c.input.items.length) throw new Error('Invalid ranking labels');
process.env.AI_JEV_ALLOWED_USER_IDS = 'synthetic-jev-live-eval';
process.env.AI_MEMORY_REVIEW_MODE = 'active';
process.env.AI_RETRIEVAL_DECISIONS_MODE = 'active';
process.env.APP_LOG_LEVEL = 'silent';
const metered:any[]=[];
for (const moduleRoot of new Set([root,'/Users/kovd3v/Documents/Projects/anthon-2.0'])) {
  mock.module(`${moduleRoot}/src/lib/ai/usage-meter.ts`,()=>({scheduleTypedDecisionUsage:(result:any,input:any)=>metered.push({operation:input.operation,...result})}));
  mock.module(`${moduleRoot}/src/lib/logger/index.ts`,()=>({createLogger:()=>({info(){},warn(){},error(){},debug(){}})}));
}
const {reviewMemoryCandidates}=await import(`${root}/src/lib/ai/memory-decisions.ts`);
const {refineRecallPlan,rankRetrievedItems}=await import(`${root}/src/lib/ai/retrieval-decisions.ts`);
const {evaluateAnswerChecks,compareAnswerCheckLabels}=await import(`${root}/src/lib/benchmark/answer-checks.ts`);
const sourceHashes=Object.fromEntries(['ai/typed-decisions.ts','ai/memory-decisions.ts','ai/retrieval-decisions.ts','benchmark/answer-checks.ts'].map(file=>[file,createHash('sha256').update(readFileSync(`${root}/src/lib/${file}`)).digest('hex')]));
const log=(data:any)=>appendFileSync(output,JSON.stringify(data)+'\n');
writeFileSync(output,JSON.stringify({type:'run',startedAt:new Date().toISOString(),root,selection,split:corpus.split,corpusSHA256:createHash('sha256').update(corpusText).digest('hex'),sourceHashes,maxRequests:80,syntheticOnly:true,metering:'mocked; provider usage journaled',runnerSHA256:createHash('sha256').update(readFileSync(import.meta.path)).digest('hex')})+'\n',{flag:'wx'});
let activeCase='', calls=0;
const originalFetch=globalThis.fetch;
globalThis.fetch=(async(url:any,init:any)=>{
 const target=new URL(String(url));
 if(target.host!=='openrouter.ai'||target.pathname!=='/api/alpha/decisions') throw new Error('Only Jev evaluation requests allowed');
 if(++calls>80)throw new Error('Evaluation request cap reached');
 const call=calls,started=performance.now();
 log({type:'request',id:activeCase,call,body:JSON.parse(init.body)});
 try{
  const response=await originalFetch(url,init);
  const raw=await response.clone().json().catch(()=>null);
  log({type:'response',id:activeCase,call,status:response.status,durationMs:Math.round(performance.now()-started),raw});
  return response;
 }catch(error){log({type:'request_error',id:activeCase,call,durationMs:Math.round(performance.now()-started),error:error instanceof Error?error.name:'unknown'});throw error;}
}) as typeof fetch;
async function run(c:any,kind:string,execute:()=>Promise<any>){
 activeCase=c.id;const start=metered.length;
 const actual=await execute(),transports=metered.slice(start);
 const expected=kind==='planning'?{conversationsEnabled:c.expected.conversationsEnabled,allowCrossChannel:c.expected.allowCrossChannel}:kind==='ranking'?c.expected.retainedIds:c.expected;
 const record={type:'case',id:c.id,kind,expected,actual,outcomeMatches:isDeepStrictEqual(actual,expected),transports};
 log(record);console.log(JSON.stringify({id:c.id,kind,match:record.outcomeMatches,received:transports[0]?.ok,durationMs:transports[0]?.durationMs,actual}));
}
if(selection==='all'||selection==='memory')for(const c of corpus.memoryCases)await run(c,'memory',async()=> (await reviewMemoryCandidates({...c.input,userId:'synthetic-jev-live-eval'})).map((r:any)=>({reject:r.reject,requiresApproval:r.requiresApproval,...(r.match?{match:{kind:r.match.kind,factId:r.match.fact.id}}:{})})));
if(selection==='all'||selection==='retrieval'){
 for(const c of corpus.planningCases)await run(c,'planning',async()=>{const r=await refineRecallPlan({...c.input,userId:'synthetic-jev-live-eval'});return{conversationsEnabled:r.conversations.enabled,allowCrossChannel:r.conversations.allowCrossChannel};});
 for(const c of corpus.rankingCases)await run(c,'ranking',async()=> (await rankRetrievedItems({...c.input,userId:'synthetic-jev-live-eval',describe:(x:any)=>x.text})).map((x:any)=>x.id));
}
if(selection==='all'||selection==='answer') for(const fixture of corpus.answerFixtures){
 activeCase=fixture.turn.scenarioId;
 const report=await evaluateAnswerChecks([fixture.turn],{timeoutMs:10000});
 const comparison=compareAnswerCheckLabels(report,[fixture]);
 log({type:'case',kind:'answer',id:activeCase,expected:fixture.expected,report,comparison});
 console.log(JSON.stringify({id:activeCase,kind:'answer',checks:report.results?.[0]?.checks,comparison}));
}
log({type:'complete',finishedAt:new Date().toISOString(),calls});
console.log(JSON.stringify({output,calls}));

