 const records=readFileSync(source,'utf8').trim().split('\n').map(x=>JSON.parse(x));
 const results=[];
 for(const f of corpus.answerFixtures){
  const row=records.find(x=>x.type==='response'&&x.id===f.turn.scenarioId);
  const original=records.find(x=>x.type==='case'&&x.id===f.turn.scenarioId).report.results[0];
