  const report=await evaluateAnswerChecks([f.turn],{request:async()=>response});
  results.push({id:f.turn.scenarioId,expected:f.expected,report,comparison:compareAnswerCheckLabels(report,[f])});
 }
 const output={mode:'offline-saved-response-replay',source,liveCalls:0,metadataNote:'Evaluator usage and latency refer to the original recorded call; replay makes no paid calls.',split,sourceSHA256:createHash('sha256').update(readFileSync(`${root}/src/lib/benchmark/answer-checks.ts`)).digest('hex'),results};
 writeFileSync(`/private/tmp/jev-calibration-${split}-replay-final.json`,JSON.stringify(output,null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({split,replayed:results.length,liveCalls:0}));
}
